package main

import (
	"fmt"
	"regexp"
)

var (
	dateRe  = regexp.MustCompile(`(?P<year>\d{4})-(?P<month>\d{2})-(?P<day>\d{2})`)
	tagRe   = regexp.MustCompile(`<b>(.*?)</b>`)
	spaceRe = regexp.MustCompile(`\s+`)
)

func main() {
	text := "下单日期 2026-10-29，联系 bob@example.com"

	// 1. 判断与提取：命名捕获组
	if dateRe.MatchString(text) {
		m := dateRe.FindStringSubmatch(text)
		fmt.Println("年:", m[dateRe.SubexpIndex("year")])
		fmt.Println("月:", m[dateRe.SubexpIndex("month")])
		fmt.Println("日:", m[dateRe.SubexpIndex("day")])
	}

	// 2. 找出所有数字
	numRe := regexp.MustCompile(`\d+`)
	fmt.Println("所有数字:", numRe.FindAllString(text, -1))

	// 3. 替换：交换用户名和域名
	mailRe := regexp.MustCompile(`(?P<user>\w+)@(?P<domain>\w+\.com)`)
	fmt.Println("改写邮箱:", mailRe.ReplaceAllString(text, "${domain}/${user}"))

	// 4. 按空白切分（首尾会切出空串）
	fmt.Println("按空白切分:", spaceRe.Split(" a  b \t c ", -1))

	// 5. 贪婪与最小匹配
	fmt.Println("贪婪:", regexp.MustCompile(`<b>.*</b>`).FindString("<b>一</b> 和 <b>二</b>"))
	fmt.Println("最小:", tagRe.FindString("<b>一</b> 和 <b>二</b>"))

	// 6. 跨行匹配
	blockRe := regexp.MustCompile(`(?s)BEGIN(.*?)END`)
	fmt.Println("跨行内容:", blockRe.FindStringSubmatch("BEGIN 第一行\n第二行 END")[1])
}
